// Snapshot the original schedule so the user can always reset to default
const DEFAULT_SCHEDULE = SCHEDULE;
const DEFAULT_SCHEDULE_ID = '__default__';
const DEFAULT_SCHEDULE_NAME = 'Seth Weekly v6 (default)';

// External store for the active schedule. Components subscribe via useSchedule().
const _scheduleListeners = new Set();
function setActiveSchedule(s) {
  SCHEDULE = s || DEFAULT_SCHEDULE;
  _scheduleListeners.forEach((fn) => fn());
}
function useSchedule() {
  const [, force] = useState(0);
  useEffect(() => {
    const listener = () => force((x) => x + 1);
    _scheduleListeners.add(listener);
    return () => _scheduleListeners.delete(listener);
  }, []);
  return SCHEDULE;
}

