// ============================================================================
// REST TIMER — global pub/sub, accessible from any component
// ============================================================================
// The timer state lives at module scope so triggering it from a deep input
// handler (e.g. logging a set) doesn't require prop-drilling. Only the floating
// RestTimerBar component subscribes to it.
let _restState = null; // { startTime, duration } | null
const _restListeners = new Set();
function _emitRest() { _restListeners.forEach((fn) => fn(_restState)); }

function startRest(durationSec = 90) {
  _restState = { startTime: Date.now(), duration: durationSec };
  _emitRest();
}
function cancelRest() {
  _restState = null;
  _emitRest();
}
function adjustRest(deltaSec) {
  if (!_restState) return;
  const elapsed = (Date.now() - _restState.startTime) / 1000;
  const newDuration = Math.max(elapsed + 5, _restState.duration + deltaSec); // never set below elapsed+5
  _restState = { ..._restState, duration: newDuration };
  _emitRest();
}
function useRestTimer() {
  const [state, setState] = useState(_restState);
  useEffect(() => {
    _restListeners.add(setState);
    return () => _restListeners.delete(setState);
  }, []);
  return state;
}

// ============================================================================
// STREAK — consecutive days following the plan (workouts done OR rest taken)
// ============================================================================
// A day counts if:
//   • it was a scheduled rest day (rest is part of the plan), OR
//   • it was a workout day and at least one exercise was completed (checkbox)
//     or any set was logged.
// Walks back from yesterday — today is in progress, so missing today doesn't
// break the streak yet. Today is counted only if already completed.
let _streakBust = 0;
const _streakListeners = new Set();
function bustStreak() {
  _streakBust++;
  _streakListeners.forEach((fn) => fn(_streakBust));
}

async function computeStreak() {
  // Pull all workout entries into a lookup once
  const keys = await storage.list('workout:');
  const workoutByDate = {};
  let earliestEngagement = null; // first date with any logged set or completed exercise
  for (const k of keys) {
    const entry = await storage.get(k);
    if (!entry) continue;
    const date = k.split(':')[1];
    if (!date) continue;
    const sets = entry.sets || entry;
    const completed = entry.completed || {};
    const hasLog =
      typeof sets === 'object' && Object.keys(sets).some((k2) => k2 !== 'scheduleDay' && k2 !== 'notes' && k2 !== 'completed' && Array.isArray(sets[k2]) && sets[k2].length > 0);
    const hasCompleted = Object.values(completed).some((v) => !!v);
    workoutByDate[date] = { hasLog, hasCompleted };
    if ((hasLog || hasCompleted) && (!earliestEngagement || date < earliestEngagement)) {
      earliestEngagement = date;
    }
  }

  // The cycle anchor also marks the start of tracking even if no workout has been
  // saved yet. Without this guard, "rest days" from before you started training
  // would count toward your streak.
  const anchor = await storage.get('cycle:anchor');
  if (anchor?.date && (!earliestEngagement || anchor.date < earliestEngagement)) {
    earliestEngagement = anchor.date;
  }

  if (!earliestEngagement) return 0;

  const dayCounts = async (dateStr) => {
    if (dateStr < earliestEngagement) return false; // before tracking started
    const scheduleDay = await resolveScheduleDay(dateStr);
    const session = SCHEDULE[scheduleDay];
    if (!session) return false;
    if (session.type === 'rest') return true; // rest day is automatically "kept"
    const w = workoutByDate[dateStr];
    return !!(w && (w.hasCompleted || w.hasLog));
  };

  let count = 0;
  // First, walk back from yesterday — if a past day fails, streak broke
  let d = addDays(today(), -1);
  for (let i = 0; i < 365 && (await dayCounts(d)); i++) {
    count++;
    d = addDays(d, -1);
  }
  // Then check today — only add if already completed/rest, never breaks
  if (await dayCounts(today())) count++;
  return count;
}

function useStreak() {
  const [bust, setBust] = useState(_streakBust);
  const [streak, setStreak] = useState(null);

  useEffect(() => {
    _streakListeners.add(setBust);
    return () => _streakListeners.delete(setBust);
  }, []);

  useEffect(() => {
    let cancelled = false;
    computeStreak().then((n) => { if (!cancelled) setStreak(n); });
    return () => { cancelled = true; };
  }, [bust]);

  return streak;
}

