// ============================================================================
// STORAGE HELPERS
// ============================================================================

const storage = {
  lastError: null,
  // Use localStorage with a prefix to namespace this app's data
  _prefix: 'sft:', // seth-fitness-tracker

  async get(key) {
    try {
      const raw = window.localStorage.getItem(this._prefix + key);
      if (raw === null) return null;
      try { return JSON.parse(raw); } catch { return raw; }
    } catch (e) {
      console.warn('storage.get failed:', key, e);
      return null;
    }
  },

  async set(key, value) {
    try {
      const serialized = typeof value === 'string' ? value : JSON.stringify(value);
      const sizeKB = serialized.length / 1024;
      if (sizeKB > 100) console.log(`storage.set ${key}: ${sizeKB.toFixed(0)} KB`);
      window.localStorage.setItem(this._prefix + key, serialized);
      this.lastError = null;
      return true;
    } catch (e) {
      const msg = e?.message || String(e) || 'unknown error';
      this.lastError = msg;
      console.error('storage.set FAILED:', key, 'error:', msg);
      // Quota exceeded is the most likely error
      if (msg.toLowerCase().includes('quota') || e?.name === 'QuotaExceededError') {
        this.lastError = 'Browser storage full. Delete old data or photos.';
      }
      return false;
    }
  },

  async list(prefix) {
    try {
      const fullPrefix = this._prefix + prefix;
      const keys = [];
      for (let i = 0; i < window.localStorage.length; i++) {
        const k = window.localStorage.key(i);
        if (k && k.startsWith(fullPrefix)) {
          keys.push(k.slice(this._prefix.length));
        }
      }
      return keys;
    } catch (e) {
      console.warn('storage.list failed:', prefix, e);
      return [];
    }
  },

  async delete(key) {
    try {
      window.localStorage.removeItem(this._prefix + key);
      return true;
    } catch (e) {
      console.warn('storage.delete failed:', key, e);
      return false;
    }
  },
};

// ============================================================================
// CRITICAL PRE-SHIP HELPERS
//   • compressImageFile — keep photos small enough to fit in localStorage
//   • exportAllData / importAllData — backup + restore so a cache clear or
//     reinstall doesn't wipe months of data
//   • ErrorBoundary — keep one crashing component from white-screening the app
// ============================================================================

// Compresses a File (from <input type="file">) using a hidden canvas and
// returns a JPEG dataURL no larger than maxDim on its longest side. We pick
// JPEG over PNG for receipts and photos because the size win is huge and
// receipts/photos compress well lossy.
async function compressImageFile(file, { maxDim = 1200, quality = 0.75 } = {}) {
  if (!file) throw new Error('No file provided');
  if (!file.type.startsWith('image/')) {
    // For PDFs and other non-image types, just return raw base64
    return await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result));
      reader.onerror = () => reject(new Error('Could not read file'));
      reader.readAsDataURL(file);
    });
  }
  const dataUrl = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(new Error('Could not read image'));
    reader.readAsDataURL(file);
  });
  return await new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        const scale = Math.min(1, maxDim / Math.max(img.width, img.height));
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#fff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      } catch (e) {
        reject(e);
      }
    };
    img.onerror = () => reject(new Error('Could not load image'));
    img.src = dataUrl;
  });
}

// Returns a tight JSON backup of every key under the sft: prefix. Note that
// localStorage values are already strings — we collect them as raw strings to
// avoid double-parsing edge cases (e.g. a value that's not valid JSON).
async function exportAllData() {
  const keys = await storage.list('');
  const data = {};
  for (const key of keys) {
    try {
      const raw = window.localStorage.getItem(storage._prefix + key);
      data[key] = raw;
    } catch (e) {
      console.warn('Could not export key:', key, e);
    }
  }
  return {
    app: 'seth-fitness-tracker',
    version: 1,
    exportedAt: new Date().toISOString(),
    keyCount: keys.length,
    data,
  };
}

function triggerDownload(filename, contents) {
  const blob = new Blob([contents], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// Imports a backup file. `mode` controls collision behavior:
//   'merge'   — only set keys that don't already exist (safest, preserves current)
//   'replace' — wipe existing app data first, then restore (full revert to backup)
async function importAllData(backup, mode = 'merge') {
  if (!backup || backup.app !== 'seth-fitness-tracker') {
    throw new Error('Not a Seth Fitness Tracker backup file');
  }
  if (!backup.data || typeof backup.data !== 'object') {
    throw new Error('Backup file is missing data');
  }
  if (mode === 'replace') {
    const existing = await storage.list('');
    for (const key of existing) await storage.delete(key);
  }
  let restored = 0;
  let skipped = 0;
  for (const [key, rawValue] of Object.entries(backup.data)) {
    if (mode === 'merge') {
      const existing = window.localStorage.getItem(storage._prefix + key);
      if (existing !== null) { skipped++; continue; }
    }
    try {
      window.localStorage.setItem(storage._prefix + key, String(rawValue));
      restored++;
    } catch (e) {
      console.warn('Could not import key:', key, e);
      skipped++;
    }
  }
  return { restored, skipped, total: Object.keys(backup.data).length };
}

// Class component because hooks can't catch render-time errors. If anything
// inside the boundary throws, we capture and show a recovery screen rather
// than letting the whole app white-screen out.
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, errorInfo) {
    this.setState({ errorInfo });
    try {
      console.error('App crashed:', error);
      console.error('Stack:', errorInfo?.componentStack);
    } catch {}
  }
  recover = () => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };
  reload = () => {
    try { window.location.reload(); } catch {}
  };
  exportBackup = async () => {
    try {
      const backup = await exportAllData();
      triggerDownload(`fitness-tracker-recovery-${new Date().toISOString().slice(0, 10)}.json`, JSON.stringify(backup, null, 2));
    } catch (e) {
      alert('Backup failed: ' + (e?.message || 'unknown error'));
    }
  };
  render() {
    if (!this.state.hasError) return this.props.children;
    return (
      <div className="min-h-screen bg-stone-950 text-stone-100 flex items-center justify-center p-5">
        <div className="max-w-md w-full">
          <div className="bg-stone-900 border border-rose-400/30 rounded-xl p-5 mb-3">
            <div className="flex items-start gap-2 mb-3">
              <AlertCircle size={20} className="text-rose-400 shrink-0 mt-0.5" />
              <div className="flex-1">
                <div className="display text-lg font-semibold text-rose-300 mb-1">Something broke</div>
                <div className="text-xs text-stone-400 leading-relaxed">
                  A component crashed. Your data is safe — nothing was written. Try recover first (resumes from a clean state). If that doesn't work, download a backup before reloading so you don't lose anything.
                </div>
              </div>
            </div>
            {this.state.error && (
              <div className="bg-stone-950 border border-stone-800 rounded-md p-2 mb-3">
                <div className="mono text-[10px] uppercase tracking-wider text-stone-500 mb-1">Error</div>
                <div className="mono text-[10px] text-rose-400/90 break-all leading-relaxed">
                  {String(this.state.error?.message || this.state.error || 'Unknown error').slice(0, 240)}
                </div>
              </div>
            )}
            <div className="space-y-2">
              <button
                onClick={this.recover}
                className="w-full bg-amber-400 hover:bg-amber-300 text-stone-950 rounded-md py-2.5 mono text-xs uppercase tracking-wider font-semibold flex items-center justify-center gap-2"
              >
                <RefreshCw size={13} /> Try to recover
              </button>
              <button
                onClick={this.exportBackup}
                className="w-full bg-stone-800 hover:bg-stone-700 text-stone-200 rounded-md py-2.5 mono text-xs uppercase tracking-wider flex items-center justify-center gap-2"
              >
                <Download size={13} /> Download backup
              </button>
              <button
                onClick={this.reload}
                className="w-full bg-stone-900 hover:bg-stone-800 border border-stone-700 text-stone-300 rounded-md py-2.5 mono text-xs uppercase tracking-wider"
              >
                Reload app
              </button>
            </div>
          </div>
          <div className="mono text-[10px] text-stone-600 text-center leading-relaxed">
            If the same crash keeps happening, the offending data is likely a single corrupted entry. Open the Settings panel and try restoring a previous backup, or contact yourself with the error message above.
          </div>
        </div>
      </div>
    );
  }
}

// ============================================================================
// FOOD SEARCH — Curated offline database + USDA fallback
// ============================================================================

// Extract a macro from USDA's foodNutrients array.
function extractMacro(nutrients, ids) {
  for (const id of ids) {
    const n = nutrients.find((x) => x.nutrientId === id || x.nutrientNumber === String(id));
    if (n && (n.value != null || n.amount != null)) {
      return Number(n.value ?? n.amount);
    }
  }
  return 0;
}

function parseUsdaFood(food) {
  const nutrients = food.foodNutrients || [];
  const isBranded = food.dataType === 'Branded';
  const cal = extractMacro(nutrients, [1008, 2047, 2048]);
  const protein = extractMacro(nutrients, [1003]);
  const carbs = extractMacro(nutrients, [1005]);
  const fat = extractMacro(nutrients, [1004]);

  let serving = '';
  if (isBranded) {
    serving = food.householdServingFullText ||
      (food.servingSize && food.servingSizeUnit ? `${food.servingSize} ${food.servingSizeUnit}` : '');
  } else {
    serving = '100 g';
  }

  const brand = food.brandOwner || food.brandName || '';
  const name = food.description || food.lowercaseDescription || 'Unknown';

  return {
    name: brand && !name.toLowerCase().includes(brand.toLowerCase()) ? `${brand} ${name}` : name,
    serving: serving || '1 serving',
    cal: Math.round(cal),
    protein: Math.round(protein * 10) / 10,
    carbs: Math.round(carbs * 10) / 10,
    fat: Math.round(fat * 10) / 10,
    source: 'USDA',
    dataType: food.dataType,
    fdcId: food.fdcId,
  };
}

