// Units available when adding/editing a pantry item. Package-type units come
// first because partial-package tracking (¾ of a box) is most natural for them.
const PANTRY_UNITS = [
  'ea', 'box', 'carton', 'bag', 'container', 'bottle', 'jar', 'can', 'pack', 'bunch', 'loaf', 'dozen',
  'g', 'kg', 'oz', 'lb', 'ml', 'l', 'cup', 'tbsp', 'tsp',
];
const PACKAGE_UNITS = new Set(['ea', 'box', 'carton', 'bag', 'container', 'bottle', 'jar', 'can', 'pack', 'bunch', 'loaf', 'dozen']);
// Quick partial-package fractions. Value is the decimal added to the whole count.
const PANTRY_FRACTIONS = [
  { label: '¼', value: 0.25 },
  { label: '⅓', value: 1 / 3 },
  { label: '½', value: 0.5 },
  { label: '⅔', value: 2 / 3 },
  { label: '¾', value: 0.75 },
];
// Format a possibly-fractional quantity for display, e.g. 1.75 → "1¾", 0.5 → "½".
function fmtPantryQty(qty) {
  const n = parseFloat(qty);
  if (!isFinite(n)) return String(qty ?? '');
  const whole = Math.floor(n + 1e-9);
  const frac = n - whole;
  let fracLabel = '';
  for (const f of PANTRY_FRACTIONS) {
    if (Math.abs(frac - f.value) < 0.02) { fracLabel = f.label; break; }
  }
  if (fracLabel) return whole > 0 ? `${whole}${fracLabel}` : fracLabel;
  // Not a clean fraction — show up to 2 decimals, trimmed
  return n % 1 === 0 ? String(whole) : String(+n.toFixed(2));
}

// Units that are physically discrete — a fraction reads as nonsense
// ("0.75 clove garlic"). For these we round to whole numbers (minimum 1) when
// parsing a recipe and when scaling quantities for display.
const COUNTABLE_UNITS = new Set([
  'ea', 'each', 'whole', 'clove', 'cloves', 'egg', 'eggs', 'can', 'cans',
  'slice', 'slices', 'head', 'heads', 'bunch', 'bunches', 'stalk', 'stalks',
  'sprig', 'sprigs', 'leaf', 'leaves', 'fillet', 'fillets', 'breast', 'breasts',
  'thigh', 'thighs', 'link', 'links', 'patty', 'patties', 'wrap', 'wraps',
  'tortilla', 'tortillas', 'pita', 'pitas', 'bun', 'buns', 'stick', 'sticks',
  'loaf', 'loaves', 'piece', 'pieces',
]);
function isCountableUnit(unit) {
  return COUNTABLE_UNITS.has(String(unit || '').toLowerCase().trim());
}

